import re

def find_numbers(text):
    return [int(n) for n in re.findall(r"\d+", text)]

import re

def mask_digits(text):
    return re.sub(r"\d", "#", text)

import re

def parse_date(text):
    match = re.search(r"(\d{4})-(\d{2})-(\d{2})", text)
    if match is None:
        return None
    return tuple(int(part) for part in match.groups())
